@dataclass(frozen=True)
class Version:                                      # immutable snapshot
    effective: date
    terms: Terms
@dataclass
class Contract:                                     # continuity
    history: list[Version] = field(default_factory=list)
    def as_of(self, on: date) -> Version | None:
        i = bisect.bisect_right(self.history, on, key=attrgetter("effective"))
        return self.history[i - 1] if i else None           # None = Missing Version
    def amend(self, effective, working):        # working = replace(current(), terms=...)
        insort(self.history, Version(effective, working), key=attrgetter("effective"))
